<?php require 'config.php';require_user();$uid=current_user()['id'];$bookingId=(int)($_GET['booking']??$_POST['booking_id']??0);$s=$pdo->prepare("SELECT b.*,d.name destination,d.price FROM bookings b JOIN destinations d ON d.id=b.destination_id WHERE b.id=? AND b.user_id=? AND b.status='approved'");$s->execute([$bookingId,$uid]);$b=$s->fetch();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$method=$_POST['method']??'';$ref=trim($_POST['transaction_ref']??'');if(!$b)$error='Only approved trip requests can be paid.';elseif(!in_array($method,['UPI','Apple Pay','Bank Transfer'],true))$error='Select a valid payment method.';elseif($ref==='')$error='Enter the transaction reference or payment note so admin can verify it.';else{$amount=(float)$b['price']*(int)$b['travelers'];$q=$pdo->prepare("INSERT INTO payments(booking_id,user_id,amount,method,transaction_ref) VALUES(?,?,?,?,?)");$q->execute([$bookingId,$uid,$amount,$method,$ref]);flash('Payment details submitted. The payment will show as submitted until an admin verifies it.');redirect('my_payments.php');}}
$settings=$pdo->query('SELECT setting_key,setting_value FROM settings')->fetchAll(PDO::FETCH_KEY_PAIR);$payrows=[];if($bookingId){$q=$pdo->prepare('SELECT * FROM payments WHERE booking_id=? AND user_id=? ORDER BY id DESC');$q->execute([$bookingId,$uid]);$payrows=$q->fetchAll();}
$page_title='Payments';require 'partials/header.php';?><section class="panel"><span class="eyebrow">SAFE & TRANSPARENT</span><h1 style="font-size:36px">Payment centre</h1><p class="muted">Choose a method and submit the transaction details for verification.</p><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><?php if(!$b):?><div class="empty">Select an approved trip from <a href="my_bookings.php"><b>My Trips</b></a> to continue to payment.</div><?php else:?><div class="alert success">Approved trip: <b><?=e($b['destination'])?></b> · Request #<?=$bookingId?> · Total: <b>₹<?=number_format((float)$b['price']*(int)$b['travelers'],2)?></b></div><div class="detail-layout"><div><h3>Pay using your preferred method</h3><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="booking_id" value="<?=$bookingId?>"><div class="payment-methods"><div class="method"><label><input type="radio" name="method" value="UPI" checked> UPI</label></div><div class="method"><label><input type="radio" name="method" value="Apple Pay"> Apple Pay</label></div><div class="method"><label><input type="radio" name="method" value="Bank Transfer"> Bank transfer</label></div></div><div class="field"><label>Transaction reference / payment note</label><input name="transaction_ref" required maxlength="190" placeholder="Enter UTR / transaction ID"></div><p class="muted">Do not enter your UPI PIN, bank password or card security code here.</p><button class="btn btn-primary">Submit payment details →</button></form></div><div><h3>UPI QR payment</h3><?php if(file_exists(__DIR__.'/assets/images/payment-qr.png')):?><img class="qr-image" src="assets/images/payment-qr.png" alt="UPI payment QR code"><?php else:?><div class="empty">Add your QR image as <b>assets/images/payment-qr.png</b>.</div><?php endif;?><p class="muted">UPI ID: <?=e($settings['upi_id']??'yourname@upi')?></p><h3>Bank transfer details</h3><p class="muted"><?=nl2br(e($settings['bank_details']??'Ask the administrator for bank details.'))?></p><p class="muted"><b>Apple Pay:</b> Requires a supported merchant/payment gateway. This page records your selected method for admin review; it does not process Apple Pay directly.</p></div></div><?php if($payrows):?><h3 style="margin-top:32px">Previous submissions</h3><div class="table-wrap"><table><tr><th>Amount</th><th>Method</th><th>Reference</th><th>Status</th></tr><?php foreach($payrows as $p):?><tr><td>₹<?=number_format((float)$p['amount'],2)?></td><td><?=e($p['method'])?></td><td><?=e($p['transaction_ref'])?></td><td><span class="status <?=e($p['status'])?>"><?=e($p['status'])?></span></td></tr><?php endforeach;?></table></div><?php endif;?><?php endif;?></section><?php require 'partials/footer.php';?>
